-- MP-0050: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='barisan-nasional' and type='alliance') then raise exception 'MP-0050: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0050: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='upko' and type='party') then raise exception 'MP-0050: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('chan-foong-hin','shahelmey-yahya','ewon-benedick') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0050: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kota kinabalu','putatan','penampang') and slug not in ('chan-foong-hin','shahelmey-yahya','ewon-benedick')) then raise exception 'MP-0050: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0050:%' and (m.source_type <> 'editorial' or e.slug not in ('chan-foong-hin','shahelmey-yahya','ewon-benedick') or m.import_key not like 'MP-0050:' || e.slug || ':%')) then raise exception 'MP-0050: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'chan-foong-hin','Chan Foong Hin','government','Deputy Minister of Agriculture and Food Security','Kota Kinabalu','Sabah','Chan Foong Hin represents Kota Kinabalu, Sabah, in the Dewan Rakyat. Current role: Deputy Minister of Agriculture and Food Security. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4211','/portraits/chan-foong-hin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P172.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4211"}, {"label": "DAP · current Sabah representatives", "url": "https://dapmalaysia.org/en/sabah-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'shahelmey-yahya','Shahelmey Yahya','government','Member of the Dewan Rakyat','Putatan','Sabah','Shahelmey Yahya represents Putatan, Sabah, in the Dewan Rakyat. Parliament records affiliation with Barisan Nasional (BN). Reports of suspended UMNO membership are recorded in the profile sources.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4212','/portraits/shahelmey-yahya.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P173.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4212"}, {"label": "UMNO suspension · confirmed report, 6 March 2025", "url": "https://www.thestar.com.my/news/nation/2025/03/06/shahelmey-has-been-officially-suspended-from-umno-confirms-putatan-umno-chief"}]'::jsonb from public.entities parent where parent.slug='barisan-nasional' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ewon-benedick','Ewon Benedick','government','Member of the Dewan Rakyat; President of UPKO','Penampang','Sabah','Ewon Benedick represents Penampang, Sabah, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; President of UPKO. Affiliated with UPKO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4213','/portraits/ewon-benedick.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P174.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4213"}, {"label": "UPKO · 2026–2029 leadership", "url": "https://www.upko.org/amt.html"}, {"label": "GRS · UPKO admission, 18 June 2026", "url": "https://www.nst.com.my/amp/news/regional/2026/06/1466676/grs-accepts-upko-newest-component-party"}]'::jsonb from public.entities parent where parent.slug='upko' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('chan-foong-hin','shahelmey-yahya','ewon-benedick') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0050: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0050:chan-foong-hin:sabah-agro-madani-400','Hold 400 Agro-Madani sales events in Sabah during 2026','Economy','in_progress',null,'2026-12-31','2026-01-11','https://www.dailyexpress.com.my/news/273709/400-sabah-agro-madani-sales','2026-01-11','https://www.dailyexpress.com.my/news/273709/400-sabah-agro-madani-sales','At the first reported Sabah programme, Chan announced the annual target for fresh-produce sales events across the state’s constituencies.','The January launch establishes activity toward the target. A later cumulative event count was not verified. The RM5 million sales target and national budget are different measures, so no completion percentage is calculated. The source’s older portfolio label is superseded by the current Parliament profile.','2026-11-10','editorial',false from public.entities e where e.slug='chan-foong-hin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

commit;
